    references:[{title:'Câmara — Lei 12.527/2011 atualizada',url:'https://www2.camara.leg.br/legin/fed/lei/2011/lei-12527-18-novembro-2011-611802-normaatualizada-pl.html',section:'Arts. 7º a 12 e 15: acesso, divulgação, pedido e recurso.'}],
